<#
.SYNOPSIS
Regenerates the sample list in the root README.md from the first-party package manifests.

.DESCRIPTION
Reads the "samples" array of every Packages/com.uee03.pretzel.*/package.json and rewrites the block between
<!-- SAMPLES:START --> and <!-- SAMPLES:END --> in README.md. Add or remove a sample in a package.json (and its
Samples~ folder) and run this script; the pre-commit hook does it for you. It fails when a manifest lists a sample
folder that does not exist, and warns about Samples~ folders that no manifest lists (Unity shows only listed samples).

.PARAMETER Check
Fails when README.md differs from the generated list, without writing it. Use in a release check.
#>
param(
    [switch]$Check
)

$ErrorActionPreference = "Stop"
$repository = (Resolve-Path (Join-Path $PSScriptRoot "..\..")).Path
$packagesRoot = Join-Path $repository "Packages"
$readmePath = Join-Path $repository "README.md"
$prefix = "com.uee03.pretzel."
$startMarker = "<!-- SAMPLES:START -->"
$endMarker = "<!-- SAMPLES:END -->"

function ConvertTo-Cell([string]$text) {
    return ($text -replace '\|', '\|' -replace '\s+', ' ').Trim()
}

$rows = New-Object System.Collections.Generic.List[string]
$packageCount = 0
$sampleCount = 0
foreach ($directory in Get-ChildItem $packagesRoot -Directory -Filter "$prefix*" | Sort-Object Name) {
    $manifestPath = Join-Path $directory.FullName "package.json"
    $manifest = [System.IO.File]::ReadAllText($manifestPath) | ConvertFrom-Json
    $samples = @($manifest.samples)
    $listedFolders = @()
    $shortName = $directory.Name.Substring($prefix.Length)
    $readmeLink = "Packages/$($directory.Name)/README.md"
    $first = $true
    foreach ($sample in $samples) {
        if (-not $sample) { continue }
        $samplePath = ([string]$sample.path).Replace("\", "/")
        $folder = Join-Path $directory.FullName $samplePath
        if (-not (Test-Path -LiteralPath $folder -PathType Container)) {
            throw "$manifestPath lists the sample '$($sample.displayName)' but '$samplePath' does not exist."
        }

        $listedFolders += (Split-Path $folder -Leaf)
        $packageCell = if ($first) { "[$shortName]($readmeLink)" } else { "" }
        $source = "[$samplePath](Packages/$($directory.Name)/$($samplePath -replace ' ', '%20'))"
        $rows.Add("| $packageCell | **$(ConvertTo-Cell $sample.displayName)** | $(ConvertTo-Cell $sample.description) | $source |")
        $first = $false
        $sampleCount++
    }

    if (-not $first) { $packageCount++ }

    $samplesRoot = Join-Path $directory.FullName "Samples~"
    if (Test-Path $samplesRoot) {
        foreach ($folder in Get-ChildItem $samplesRoot -Directory) {
            if ($listedFolders -notcontains $folder.Name) {
                Write-Warning "$($directory.Name): Samples~/$($folder.Name) is not listed in package.json, so Unity will not offer it."
            }
        }
    }
}

$block = New-Object System.Collections.Generic.List[string]
$block.Add($startMarker)
$block.Add("<!-- Generated by .github/scripts/Update-SampleCatalog.ps1 from each package.json. Do not edit by hand. -->")
$block.Add("")
$block.Add("$sampleCount samples in $packageCount packages.")
$block.Add("")
$block.Add("| Package | Sample | What it shows | Source |")
$block.Add("|---|---|---|---|")
foreach ($row in $rows) { $block.Add($row) }
$block.Add($endMarker)
$generated = ($block -join "`n")

$readme = [System.IO.File]::ReadAllText($readmePath)
$crlf = $readme.Contains("`r`n")
$normalized = $readme.Replace("`r`n", "`n")
$start = $normalized.IndexOf($startMarker, [System.StringComparison]::Ordinal)
$end = $normalized.IndexOf($endMarker, [System.StringComparison]::Ordinal)
if ($start -lt 0 -or $end -lt $start) {
    throw "README.md needs the markers $startMarker and $endMarker around the sample list."
}

$updated = $normalized.Substring(0, $start) + $generated + $normalized.Substring($end + $endMarker.Length)
if ($Check) {
    if ($updated -ne $normalized) {
        throw "The sample list in README.md is out of date. Run .github/scripts/Update-SampleCatalog.ps1 and commit the result."
    }

    Write-Output "README.md sample list is up to date ($sampleCount samples in $packageCount packages)."
    return
}

if ($updated -eq $normalized) {
    Write-Output "README.md sample list is already up to date ($sampleCount samples in $packageCount packages)."
    return
}

if ($crlf) { $updated = $updated.Replace("`n", "`r`n") }
[System.IO.File]::WriteAllText($readmePath, $updated, (New-Object System.Text.UTF8Encoding($false)))
Write-Output "Updated the sample list in README.md ($sampleCount samples in $packageCount packages)."
